CREATE PROCEDURE dbo.ptu_stream
AS
BEGIN
    SET NOCOUNT ON;

    SELECT o.order_id
    FROM dbo.orders AS o
    INNER JOIN dbo.customers AS c
        ON c.customer_id = o.customer_id;
END;

CREATE PROCEDURE dbo.ptu_stream
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @i INT;

    DECLARE order_cursor CURSOR FAST_FORWARD FOR
        SELECT o.order_id
        FROM dbo.orders AS o
        INNER JOIN dbo.customers AS c
            ON c.customer_id = o.customer_id;

    OPEN order_cursor;

    FETCH NEXT FROM order_cursor INTO @i;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SELECT @i AS order_id;
        FETCH NEXT FROM order_cursor INTO @i;
    END;

    CLOSE order_cursor;
    DEALLOCATE order_cursor;
END;

